//! The sample dataset behind "Try a sample dataset": made-up orders,
//! generated by DuckDB the first time it's asked for (nothing large ships
//! with the app) and kept in the app's data folder.

use std::path::{Path, PathBuf};

use crate::engine::sql::literal;
use crate::engine::{Engine, Param};
use crate::error::Result;

pub const SAMPLE_FILE: &str = "sample_orders.csv";
pub const SAMPLE_ROWS: u64 = 50_000;

/// Products with their category and list price.
const PRODUCTS: [(&str, &str, f64); 12] = [
    ("Laptop", "Electronics", 899.0),
    ("Monitor", "Electronics", 249.0),
    ("Headphones", "Electronics", 129.0),
    ("Desk chair", "Furniture", 199.0),
    ("Standing desk", "Furniture", 449.0),
    ("Bookshelf", "Furniture", 159.0),
    ("Notebook", "Office", 4.5),
    ("Pen set", "Office", 12.0),
    ("Printer paper", "Office", 8.0),
    ("Coffee beans", "Grocery", 14.0),
    ("Green tea", "Grocery", 9.0),
    ("Olive oil", "Grocery", 11.0),
];

/// The query that makes the orders: two years of them, a mix of types
/// (dates, text, decimals, booleans) and a few empty customers, so filters,
/// charts, profiles and quality checks all have something to show. Every
/// value comes from `hash` of the row number, so the file is the same each
/// time.
fn sample_sql() -> String {
    let products = PRODUCTS
        .iter()
        .map(|(p, c, price)| {
            format!(
                "{{'product': {}, 'category': {}, 'price': {price}}}",
                literal(&Param::Text(p.to_string())),
                literal(&Param::Text(c.to_string()))
            )
        })
        .collect::<Vec<_>>()
        .join(", ");
    let n = PRODUCTS.len();
    format!(
        "SELECT order_id, order_date, region, p.product AS product, p.category AS category, \
           quantity, CAST(p.price * (0.9 + r5 % 21 / 100.0) AS DECIMAL(10, 2)) AS unit_price, \
           CAST([0, 0, 0, 0.05, 0.1, 0.2][1 + r6 % 6] AS DECIMAL(3, 2)) AS discount, \
           customer, returned \
         FROM ( \
           SELECT range + 1 AS order_id, \
             DATE '2023-01-01' + CAST(hash(range, 1) % 731 AS INTEGER) AS order_date, \
             ['North', 'South', 'East', 'West', 'Central'][1 + CAST(hash(range, 2) % 5 AS INTEGER)] \
               AS region, \
             [{products}][1 + CAST(hash(range, 3) % {n} AS INTEGER)] AS p, \
             1 + CAST(floor(pow(hash(range, 4) % 1000 / 1000.0, 3) * 10) AS INTEGER) AS quantity, \
             CAST(hash(range, 5) % 1000 AS INTEGER) AS r5, \
             CAST(hash(range, 6) % 1000 AS INTEGER) AS r6, \
             CASE WHEN hash(range, 7) % 200 = 0 THEN NULL \
               ELSE printf('C%04d', hash(range, 8) % 2500) END AS customer, \
             hash(range, 9) % 100 < 4 AS returned \
           FROM range({SAMPLE_ROWS}) \
         ) ORDER BY order_id"
    )
}

/// The sample file in `dir`, written first if it isn't there yet.
pub fn sample_dataset(engine: &Engine, dir: &Path) -> Result<PathBuf> {
    let path = dir.join(SAMPLE_FILE);
    if std::fs::metadata(&path).is_ok_and(|m| m.len() > 0) {
        return Ok(path);
    }
    std::fs::create_dir_all(dir)?;
    // Written next to it, then renamed: never a half-written sample.
    let partial = dir.join(format!("{SAMPLE_FILE}.partial"));
    let target = Param::Text(partial.to_string_lossy().into_owned());
    engine.execute_batch(&format!(
        "COPY ({}) TO {} (FORMAT csv, HEADER)",
        sample_sql(),
        literal(&target)
    ))?;
    std::fs::rename(&partial, &path)?;
    Ok(path)
}
